import React, { useState, useRef, useEffect } from 'react';
import { Container, Row, Col, Card, Form, Button, Alert, Spinner, Nav, Tab, InputGroup } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import FilePreview from '../components/FilePreview';
import { usePortfolio } from '../context/PortfolioContext';
import BreezeConfig from '../services/BreezeConfig';
import breezeService from '../services/BreezeService';
import logger from '../services/LoggerService';
import { FaUpload, FaFileAlt, FaExclamationTriangle, FaDownload, FaKey } from 'react-icons/fa';
import { ProgressBar } from 'react-bootstrap';

const ImportPortfolio = () => {
  const navigate = useNavigate();
  const { 
    portfolio, 
    processTransactionsFile, 
    processSummaryFile,
    updateTransactionsFile,
    loading, 
    error, 
    selectedBroker,
    setBroker,
    setLoading,
    setError
  } = usePortfolio();

  const [file, setFile] = useState(null);
  const [fileType, setFileType] = useState(portfolio ? 'summary' : 'transactions');
  const [broker, setBrokerState] = useState(selectedBroker || 'generic');
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [previewData, setPreviewData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [portfolioName, setPortfolioName] = useState(portfolio ? portfolio.name : 'My Portfolio');
  const [isUpdate, setIsUpdate] = useState(false);
  const [needsBreezeCredentials, setNeedsBreezeCredentials] = useState(false);
  const [breezeCredentials, setBreezeCredentials] = useState({
    apiKey: BreezeConfig.apiKey,
    apiSecret: BreezeConfig.apiSecret,
    sessionKey: ''
  });
  const [mappedFields, setMappedFields] = useState({
    transactions: {
      date: '',
      symbol: '',
      action: '',
      quantity: '',
      price: '',
      brokerage: '',
      companyName: ''
    },
    summary: {
      symbol: '',
      companyName: '',
      quantity: '',
      avgCostPrice: '',
      currentPrice: '',
      valueAtCost: '',
      valueAtMarket: '',
      unrealizedPL: '',
      unrealizedPLPercent: ''
    }
  });
  const [isBreezeLoading, setIsBreezeLoading] = useState(false);
  const [breezeError, setBreezeError] = useState('');
  const [breezeStatus, setBreezeStatus] = useState('');
  const [dateRange, setDateRange] = useState({
    fromDate: new Date(new Date().setFullYear(new Date().getFullYear() - 1)).toISOString().split('T')[0],
    toDate: new Date().toISOString().split('T')[0]
  });

  // Add new state for session key generation status
  const [isSessionKeyGenerated, setIsSessionKeyGenerated] = useState(false);
  const [isGeneratingSessionKey, setIsGeneratingSessionKey] = useState(false);
  const [sessionKeyError, setSessionKeyError] = useState('');

  const fileInputRef = useRef(null);

  // Set default file type based on portfolio existence
  useEffect(() => {
    if (portfolio) {
      setFileType('summary');
      setPortfolioName(portfolio.name);
      setIsUpdate(true);
      setBrokerState(portfolio.broker || 'generic');
    } else {
      setFileType('transactions');
      setIsUpdate(false);
    }
  }, [portfolio]);

  // Check if Breeze credentials are default values
  useEffect(() => {
    if (broker.toLowerCase() === 'icici') {
      const hasDefaultCredentials = 
        BreezeConfig.apiKey === 'YOUR_API_KEY' || 
        BreezeConfig.apiSecret === 'YOUR_API_SECRET';

      setNeedsBreezeCredentials(hasDefaultCredentials);
    } else {
      setNeedsBreezeCredentials(false);
    }
  }, [broker]);

  // Effect to check if Breeze credentials exist
  useEffect(() => {
    if (broker.toLowerCase() === 'icici') {
      const storedCreds = breezeService.getStoredCredentials();
      if (storedCreds && storedCreds.apiKey) {
        logger.info('ImportPortfolio', 'Found stored Breeze credentials');

        // Update UI state if needed
        setBreezeCredentials(prev => ({
          ...prev,
          apiKey: storedCreds.apiKey || '',
          apiSecret: storedCreds.apiSecret || '',
          sessionKey: storedCreds.sessionKey || ''
        }));
      }
    }
  }, [broker]);

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setFile(selectedFile);
      readFilePreview(selectedFile);
    }
  };

  const readFilePreview = (file) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target.result;
      const lines = content.split('\n');

      if (lines.length > 0) {
        const headerLine = lines[0];
        const headerFields = headerLine.split(',').map(h => h.trim());
        setHeaders(headerFields);

        // Get up to 5 rows for preview
        const previewRows = [];
        for (let i = 1; i < Math.min(lines.length, 6); i++) {
          const line = lines[i].trim();
          if (line) {
            const values = line.split(',').map(v => v.trim());
            previewRows.push(values);
          }
        }
        setPreviewData(previewRows);
      }
    };
    reader.readAsText(file);
  };

  const handleFieldMapping = (fileType, field, headerName) => {
    setMappedFields(prev => ({
      ...prev,
      [fileType]: {
        ...prev[fileType],
        [field]: headerName
      }
    }));
  };

  const handleFileTypeChange = (type) => {
    setFileType(type);
  };

  const handleBrokerChange = (e) => {
    const selectedBroker = e.target.value;
    setBrokerState(selectedBroker);
    setBroker(selectedBroker);

    // If ICICI is selected, adjust file type to transactions only
    if (selectedBroker.toLowerCase() === 'icici') {
      setFileType('transactions');
    }
  };

  const handleCredentialChange = (field, value) => {
    setBreezeCredentials(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    logger.info('ImportPortfolio', 'Form submitted for file upload');

    if (!file) {
      logger.warn('ImportPortfolio', 'No file selected');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Check if we need to initialize Breeze API for ICICI broker
      if (broker.toLowerCase() === 'icici') {
        logger.info('ImportPortfolio', 'ICICI broker selected, saving credentials');

        // Save Breeze credentials before processing
        await breezeService.initialize({
          apiKey: breezeCredentials.apiKey,
          apiSecret: breezeCredentials.apiSecret,
          sessionKey: breezeCredentials.sessionKey
        });
      }

      // Process based on file type
      if (fileType === 'transactions') {
        logger.info('ImportPortfolio', 'Processing transactions file');
        await processTransactionsFile(file, headers, mappedFields[fileType], portfolioName, broker);
      } else {
        logger.info('ImportPortfolio', 'Processing summary file');
        await processSummaryFile(file, headers, mappedFields[fileType], portfolioName);
      }

      logger.info('ImportPortfolio', 'File processed successfully');
      navigate('/dashboard');
    } catch (err) {
      logger.error('ImportPortfolio', 'Error processing file', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const downloadSampleCSV = () => {
    let csvContent = '';

    if (fileType === 'transactions') {
      csvContent = 'Date,Symbol,Action,Quantity,Price,Brokerage,Company Name\n' +
        '2023-01-15,AAPL,BUY,10,175.25,5.99,Apple Inc.\n' +
        '2023-02-20,MSFT,BUY,5,280.50,5.99,Microsoft Corporation\n' +
        '2023-03-10,AAPL,SELL,3,180.75,5.99,Apple Inc.\n' +
        '2023-04-05,GOOGL,BUY,2,2750.00,7.99,Alphabet Inc.\n' +
        '2023-05-12,AMZN,BUY,8,135.75,5.99,Amazon.com Inc.';
    } else {
      csvContent = 'Symbol,Company Name,Quantity,Avg Cost Price,Current Price,Value at Cost,Value at Market,Unrealized P/L,Unrealized P/L %\n' +
        'AAPL,Apple Inc.,25,150.25,180.50,3756.25,4512.50,756.25,20.13\n' +
        'MSFT,Microsoft Corporation,15,250.75,300.25,3761.25,4503.75,742.50,19.74\n' +
        'GOOGL,Alphabet Inc.,5,2500.00,2800.00,12500.00,14000.00,1500.00,12.00\n' +
        'AMZN,Amazon.com Inc.,20,120.50,150.25,2410.00,3005.00,595.00,24.69';
    }

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileType === 'transactions' ? 'sample_transactions.csv' : 'sample_portfolio_summary.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const renderFieldMappingForm = () => {
    const currentMapping = mappedFields[fileType];
    const fields = Object.keys(currentMapping);

    return (
      <Card className="mb-4">
        <Card.Header>Map File Columns</Card.Header>
        <Card.Body>
          <p className="text-muted mb-3">
            Match your file columns to the required fields. Required fields are marked with *.
          </p>

          <Row>
            {fields.map(field => (
              <Col md={6} key={field} className="mb-3">
                <Form.Group>
                  <Form.Label>
                    {field.charAt(0).toUpperCase() + field.slice(1).replace(/([A-Z])/g, ' $1')}
                    {(fileType === 'transactions' && ['date', 'symbol', 'action', 'quantity', 'price'].includes(field)) ||
                     (fileType === 'summary' && ['symbol', 'quantity', 'avgCostPrice', 'currentPrice'].includes(field)) 
                      ? ' *' : ''}
                  </Form.Label>
                  <Form.Select 
                    value={currentMapping[field]} 
                    onChange={(e) => handleFieldMapping(fileType, field, e.target.value)}
                  >
                    <option value="">-- Select Column --</option>
                    {headers.map((header, index) => (
                      <option key={index} value={header}>{header}</option>
                    ))}
                  </Form.Select>
                </Form.Group>
              </Col>
            ))}
          </Row>
        </Card.Body>
      </Card>
    );
  };

  /**
   * Initialize Breeze API with user credentials
   */
  const initializeBreezeAPI = async () => {
    try {
      setIsBreezeLoading(true);
      setBreezeError('');
      setBreezeStatus('Connecting to ICICI Direct Breeze API...');

      const { apiKey, apiSecret, sessionKey } = breezeCredentials;

      if (!apiKey || !apiSecret) {
        setBreezeError('API Key and API Secret are required');
        setIsBreezeLoading(false);
        return false;
      }

      logger.info('ImportPortfolio', 'Initializing Breeze API with user credentials');

      await breezeService.initialize(apiKey, apiSecret, sessionKey);

      setBreezeStatus('Successfully connected to ICICI Direct Breeze API');
      setIsBreezeLoading(false);
      return true;
    } catch (error) {
      logger.error('ImportPortfolio', 'Breeze API initialization failed', error);
      setBreezeError(`Failed to connect to ICICI Direct: ${error.message}`);
      setBreezeStatus('');
      setIsBreezeLoading(false);
      return false;
    }
  };

  /**
   * Generate a session key for the Breeze API
   */
  const generateSessionKey = async () => {
    try {
      setIsGeneratingSessionKey(true);
      setBreezeError('');

      const { apiKey, apiSecret } = breezeCredentials;

      if (!apiKey || !apiSecret) {
        setBreezeError('API Key and API Secret are required to generate a session key');
        setIsGeneratingSessionKey(false);
        return;
      }

      setBreezeStatus('Generating session key...');

      // Call the BreezeService to get a session key
      const sessionKey = await breezeService.getSessionKey(apiKey, apiSecret);

      // Update the state with the new session key
      setBreezeCredentials(prev => ({
        ...prev,
        sessionKey
      }));

      setBreezeStatus('Session key generated successfully');
      setIsSessionKeyGenerated(true);

      // After generating the key, initialize the API with the new credentials
      await breezeService.initialize(apiKey, apiSecret, sessionKey);

    } catch (error) {
      logger.error('ImportPortfolio', 'Session key generation failed', error);
      setBreezeError(`Failed to generate session key: ${error.message}`);
      setSessionKeyError(error.message);
    } finally {
      setIsGeneratingSessionKey(false);
    }
  };

  // Update the renderBreezeCredentialsForm function
  const renderBreezeCredentialsForm = () => {
    if (!needsBreezeCredentials && broker.toLowerCase() !== 'icici') return null;

    // Create a development mode notice if in development mode
    const isDevelopment = process.env.NODE_ENV === 'development';

    return (
      <Card className="mb-4 border-warning">
        <Card.Header className="bg-warning text-dark">Breeze API Credentials Required</Card.Header>
        <Card.Body>
          <p className="mb-3">
            You need to provide your ICICI Direct Breeze API credentials to continue. These will be used to resolve stock codes and fetch price data.
          </p>

          {breezeError && (
            <Alert variant="danger">
              {breezeError}
            </Alert>
          )}

          {breezeStatus && (
            <Alert variant="info">
              {breezeStatus}
            </Alert>
          )}

          <Form.Group className="mb-3">
            <Form.Label>API Key</Form.Label>
            <Form.Control
              type="text"
              placeholder="Enter your ICICI Direct API Key"
              value={breezeCredentials.apiKey}
              onChange={(e) => setBreezeCredentials({ ...breezeCredentials, apiKey: e.target.value })}
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>API Secret</Form.Label>
            <Form.Control
              type="password"
              placeholder="Enter your ICICI Direct API Secret"
              value={breezeCredentials.apiSecret}
              onChange={(e) => setBreezeCredentials({ ...breezeCredentials, apiSecret: e.target.value })}
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Session Key</Form.Label>
            <InputGroup>
              <Form.Control
                type="text"
                placeholder="Enter or generate a session key"
                value={breezeCredentials.sessionKey}
                onChange={(e) => setBreezeCredentials({ ...breezeCredentials, sessionKey: e.target.value })}
              />
              <Button 
                variant="outline-secondary"
                onClick={generateSessionKey}
                disabled={isGeneratingSessionKey || !breezeCredentials.apiKey || !breezeCredentials.apiSecret}
              >
                {isGeneratingSessionKey ? (
                  <>
                    <Spinner animation="border" size="sm" className="me-1" />
                    Generating...
                  </>
                ) : (
                  <>
                    <FaKey className="me-1" />
                    Generate
                  </>
                )}
              </Button>
            </InputGroup>
            {isSessionKeyGenerated && (
              <Form.Text className="text-success">
                Session key successfully generated
              </Form.Text>
            )}
            {sessionKeyError && (
              <Form.Text className="text-danger">
                {sessionKeyError}
              </Form.Text>
            )}
            <Form.Text className="text-muted">
              The session key is used to authenticate with the ICICI Direct Breeze API
            </Form.Text>
          </Form.Group>

          {isDevelopment && (
            <Alert variant="info">
              <Alert.Heading>Development Mode</Alert.Heading>
              <p>You are running in development mode. The session key will be saved in localStorage for future use.</p>
            </Alert>
          )}
        </Card.Body>
      </Card>
    );
  };

  // Download portfolio summary from Breeze API
  const downloadPortfolioSummary = async () => {
    logger.info('ImportPortfolio', 'Attempting to download portfolio summary from ICICI Direct');
    setIsBreezeLoading(true);
    setBreezeError('');
    setBreezeStatus('Downloading portfolio summary...');

    try {
      // First ensure API is initialized
      if (!breezeService.isReady()) {
        const initialized = await initializeBreezeAPI();
        if (!initialized) return;
      }

      // Download the summary
      const summaryFile = await breezeService.downloadPortfolioSummary();
      setBreezeStatus('Portfolio summary downloaded successfully');

      // Process the summary file
      logger.info('ImportPortfolio', 'Processing downloaded summary file');
      await processSummaryFile(summaryFile);

      logger.info('ImportPortfolio', 'Summary file processed successfully');
    } catch (error) {
      setBreezeError(`Failed to download portfolio: ${error.message}`);
      logger.error('ImportPortfolio', 'Portfolio summary download failed', error);
    } finally {
      setIsBreezeLoading(false);
    }
  };

  // Download transactions from Breeze API
  const downloadTransactions = async () => {
    logger.info('ImportPortfolio', `Attempting to download transactions from ${dateRange.fromDate} to ${dateRange.toDate}`);
    setIsBreezeLoading(true);
    setBreezeError('');
    setBreezeStatus(`Downloading transactions from ${dateRange.fromDate} to ${dateRange.toDate}...`);

    try {
      // First ensure API is initialized
      if (!breezeService.isReady()) {
        const initialized = await initializeBreezeAPI();
        if (!initialized) return;
      }

      // Download the transactions
      const transactionsFile = await breezeService.downloadTransactionsFile(dateRange.fromDate, dateRange.toDate);
      setBreezeStatus('Transactions downloaded successfully');

      // Process the transactions file
      logger.info('ImportPortfolio', 'Processing downloaded transactions file');
      await processTransactionsFile(transactionsFile);

      logger.info('ImportPortfolio', 'Transactions file processed successfully');
    } catch (error) {
      setBreezeError(`Failed to download transactions: ${error.message}`);
      logger.error('ImportPortfolio', 'Transactions download failed', error);
    } finally {
      setIsBreezeLoading(false);
    }
  };

  // Handle date range change
  const handleDateChange = (e) => {
    const { name, value } = e.target;
    setDateRange(prev => ({
      ...prev,
      [name]: value
    }));
    logger.debug('ImportPortfolio', `Date range updated`, { [name]: value });
  };

  return (
    <Container className="mt-4">
      <h1 className="mb-4">
        {isUpdate ? 'Update Portfolio Data' : 'Import Portfolio Data'}
      </h1>

      {message.text && (
        <Alert variant={message.type}>
          {message.text}
          {message.type === 'success' && (
            <div className="mt-2">
              <Button variant="primary" onClick={() => navigate('/dashboard')}>
                View Portfolio
              </Button>
            </div>
          )}
        </Alert>
      )}

      {portfolio && (
        <Alert variant="info" className="mb-4">
          <Alert.Heading>Portfolio Already Exists</Alert.Heading>
          <p>
            You already have a portfolio loaded. Choose an option below to update it:
          </p>
          <div className="d-flex mt-3">
            <Button 
              variant={fileType === 'transactions' ? 'primary' : 'outline-primary'} 
              className="me-2"
              onClick={() => setFileType('transactions')}
            >
              Update Transactions
            </Button>
            {portfolio.broker !== 'icici' && (
              <Button 
                variant={fileType === 'summary' ? 'primary' : 'outline-primary'}
                onClick={() => setFileType('summary')}
              >
                Update Market Values
              </Button>
            )}
          </div>
        </Alert>
      )}

      <Row>
        <Col lg={6} className="mb-4">
          <Card>
            <Card.Body>
              <Card.Title>{isUpdate ? 'Update Portfolio' : 'Upload Portfolio File'}</Card.Title>
              <Card.Text>
                {isUpdate 
                  ? `Update your ${fileType === 'transactions' ? 'transactions' : 'market values'} for ${portfolio?.name || 'your portfolio'}.`
                  : 'Import your portfolio data from a CSV file.'}
              </Card.Text>

              <Form onSubmit={handleSubmit}>
                <Form.Group className="mb-3">
                  <Form.Label>Portfolio Name</Form.Label>
                  <Form.Control
                    type="text"
                    value={portfolioName}
                    onChange={(e) => setPortfolioName(e.target.value)}
                    disabled={loading}
                    placeholder="Enter a name for your portfolio"
                  />
                </Form.Group>

                <Form.Group className="mb-3">
                  <Form.Label>Broker</Form.Label>
                  <Form.Select 
                    value={broker} 
                    onChange={handleBrokerChange}
                    disabled={loading || isUpdate}
                  >
                    <option value="generic">Generic / Other</option>
                    <option value="icici">ICICI Direct</option>
                  </Form.Select>
                  <Form.Text className="text-muted">
                    {broker === 'icici' 
                      ? 'ICICI Direct: We will use the Breeze API to resolve stock codes and fetch current prices.'
                      : 'Generic: Upload your portfolio data in CSV format.'}
                  </Form.Text>
                </Form.Group>

                {renderBreezeCredentialsForm()}

                <Form.Group className="mb-3">
                  <Form.Label>File Type</Form.Label>
                  <Form.Select 
                    value={fileType} 
                    onChange={(e) => setFileType(e.target.value)}
                    disabled={loading || (portfolio && fileType === 'summary') || broker === 'icici'}
                  >
                    <option value="transactions">Transactions File</option>
                    {broker !== 'icici' && <option value="summary">Portfolio Summary File</option>}
                  </Form.Select>
                  <Form.Text className="text-muted">
                    {fileType === 'transactions' 
                      ? broker === 'icici'
                        ? 'Upload a CSV file with your buy/sell transactions. We will use Breeze API to get current prices.'
                        : 'Upload a CSV file with your buy/sell transactions. We will calculate current prices using simulated data.'
                      : 'Upload a CSV file with your current portfolio holdings and their market values.'}
                  </Form.Text>
                </Form.Group>

                {broker.toLowerCase() === 'icici' && (
                  <Card className="mb-3 bg-light">
                    <Card.Body>
                      <Card.Title>Download from ICICI Direct</Card.Title>
                      <p className="text-muted small">
                        You can download your portfolio data directly from ICICI Direct using the Breeze API.
                      </p>

                      {breezeStatus && !breezeError && (
                        <Alert variant="info" className="mb-3">
                          <p className="mb-0">{breezeStatus}</p>
                        </Alert>
                      )}

                      {breezeError && (
                        <Alert variant="danger" className="mb-3">
                          <p className="mb-0">{breezeError}</p>
                        </Alert>
                      )}

                      <div className="d-grid gap-2 mb-3">
                        <Button 
                          variant="success" 
                          onClick={downloadPortfolioSummary}
                          disabled={isBreezeLoading || !breezeCredentials.apiKey || !breezeCredentials.apiSecret || !breezeCredentials.sessionKey}
                        >
                          <FaDownload className="me-2" />
                          Download Current Portfolio
                        </Button>
                      </div>

                      <hr className="my-3" />

                      <Card.Subtitle className="mb-2">Download Transaction History</Card.Subtitle>
                      <Row className="g-2 mb-3">
                        <Col>
                          <Form.Group>
                            <Form.Label>From Date</Form.Label>
                            <Form.Control 
                              type="date" 
                              name="fromDate"
                              value={dateRange.fromDate}
                              onChange={handleDateChange}
                            />
                          </Form.Group>
                        </Col>
                        <Col>
                          <Form.Group>
                            <Form.Label>To Date</Form.Label>
                            <Form.Control 
                              type="date" 
                              name="toDate"
                              value={dateRange.toDate}
                              onChange={handleDateChange}
                            />
                          </Form.Group>
                        </Col>
                      </Row>

                      <div className="d-grid">
                        <Button 
                          variant="success" 
                          onClick={downloadTransactions}
                          disabled={isBreezeLoading || !breezeCredentials.apiKey || !breezeCredentials.apiSecret || !breezeCredentials.sessionKey}
                        >
                          <FaDownload className="me-2" />
                          Download Transactions
                        </Button>
                      </div>
                    </Card.Body>
                  </Card>
                )}

                <Form.Group className="mb-3">
                  <Form.Label>Choose File</Form.Label>
                  <div className="d-flex">
                    <Form.Control 
                      type="file" 
                      accept=".csv" 
                      onChange={handleFileChange}
                      ref={fileInputRef}
                      disabled={loading}
                    />
                    <Button 
                      variant="outline-secondary" 
                      onClick={downloadSampleCSV}
                      className="ms-2"
                      disabled={loading}
                    >
                      Download Sample
                    </Button>
                  </div>

                  {file && (
                    <div className="mt-2 mb-3">
                      <p><strong>Selected file:</strong> {file.name}</p>
                    </div>
                  )}

                  <FilePreview previewData={previewData} headers={headers} />
                </Form.Group>

                {previewData.length > 0 && renderFieldMappingForm()}

                <Button 
                  variant="primary" 
                  type="submit" 
                  disabled={!file || loading}
                >
                  {loading ? (
                    <>
                      <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" className="me-2" />
                      Processing...
                    </>
                  ) : isUpdate ? 'Update Portfolio' : 'Upload Portfolio'}
                </Button>
              </Form>
            </Card.Body>
          </Card>
        </Col>

        <Col lg={6}>
          <Card>
            <Card.Body>
              <Card.Title>File Format Guidelines</Card.Title>

              <Tab.Container defaultActiveKey={fileType}>
                <Nav variant="tabs" className="mb-3">
                  <Nav.Item>
                    <Nav.Link eventKey="transactions">Transactions File</Nav.Link>
                  </Nav.Item>
                  {broker !== 'icici' && (
                    <Nav.Item>
                      <Nav.Link eventKey="summary">Summary File</Nav.Link>
                    </Nav.Item>
                  )}
                </Nav>

                <Tab.Content>
                  <Tab.Pane eventKey="transactions">
                    <div className="mt-3">
                      <h5>Transaction File Format</h5>
                      <p>Your transaction file should contain the following information:</p>

                      <ul>
                        <li><strong>Date:</strong> Date of transaction (YYYY-MM-DD format)</li>
                        <li><strong>Symbol:</strong> The ticker symbol of the security</li>
                        <li><strong>Action:</strong> BUY or SELL</li>
                        <li><strong>Quantity:</strong> Number of shares</li>
                        <li><strong>Price:</strong> Price per share in ₹</li>
                        <li><strong>Brokerage:</strong> Any transaction fees in ₹ (optional)</li>
                        <li><strong>Company Name:</strong> The full name of the company (optional)</li>
                      </ul>

                      {broker === 'icici' && (
                        <Alert variant="info">
                          <strong>ICICI Direct:</strong> When using ICICI Direct as your broker, we'll use the Breeze API to:
                          <ul>
                            <li>Resolve your stock codes to NSE tickers</li>
                            <li>Fetch real-time prices for your holdings</li>
                            <li>Calculate portfolio performance using historical price data</li>
                          </ul>
                        </Alert>
                      )}
                    </div>
                  </Tab.Pane>

                  <Tab.Pane eventKey="summary">
                    <div className="mt-3">
                      <h5>Summary File Format</h5>
                      <p>Your portfolio summary file should contain the following information:</p>

                      <ul>
                        <li><strong>Symbol:</strong> The ticker symbol of the security</li>
                        <li><strong>Company Name:</strong> The full name of the company (optional)</li>
                        <li><strong>Quantity:</strong> Number of shares held</li>
                        <li><strong>Avg Cost Price:</strong> Average cost of acquisition per share in ₹</li>
                        <li><strong>Current Price:</strong> Current market price per share in ₹</li>
                        <li><strong>Value at Cost:</strong> Total cost of acquisition in ₹ (optional)</li>
                        <li><strong>Value at Market:</strong> Current market value in ₹ (optional)</li>
                        <li><strong>Unrealized P/L:</strong> Unrealized profit/loss in ₹ (optional)</li>
                        <li><strong>Unrealized P/L %:</strong> Unrealized profit/loss percentage (optional)</li>
                      </ul>
                    </div>
                  </Tab.Pane>
                </Tab.Content>
              </Tab.Container>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default ImportPortfolio;
